select pg_temp.assert_true(to_regprocedure('public.claim_performance_review_mail(uuid,integer)') is not null,'service claim RPC exists');
select pg_temp.assert_true((select bool_and(relrowsecurity and relforcerowsecurity) from pg_class where oid='private.performance_review_mail_outbox'::regclass),'outbox forces RLS');
select pg_temp.assert_true(not exists(select 1 from (values('anon'),('authenticated'),('service_role')) r(role) where has_table_privilege(r.role,'private.performance_review_mail_outbox','SELECT,INSERT,UPDATE,DELETE')),'no API direct outbox access');
set local role authenticated;
select pg_temp.expect_state('select * from public.claim_performance_review_mail()','42501');
reset role;
set local role anon;
select pg_temp.expect_state('select * from public.claim_performance_review_mail()','42501');
reset role;
set local role service_role;
select pg_temp.expect_state('select * from private.performance_review_mail_outbox','42501');
select pg_temp.expect_state('select * from public.claim_performance_review_mail(null,0)','22023');
select pg_temp.expect_state('select * from public.claim_performance_review_mail(null,11)','22023');
select set_config('test.claim',(select to_jsonb(c)::text from public.claim_performance_review_mail(current_setting('test.review_id')::uuid,1) c),true);
select pg_temp.assert_true((select array_agg(k order by k)=array['claim_token','delivery_id','payload','review_id'] from jsonb_object_keys(current_setting('test.claim')::jsonb) k),'claim has exactly the four contract columns');
select pg_temp.assert_true((select array_agg(k order by k)=array['document','finalisedAt','managerNote','reviewCode','reviewId'] from jsonb_object_keys(current_setting('test.claim')::jsonb->'payload') k),'server-owned payload has exactly five fields');
select pg_temp.assert_true(current_setting('test.claim')::jsonb->'payload'->>'managerNote'='Synthetic private note' and not(current_setting('test.claim')::jsonb->'payload'->'document' ? 'managerNote'),'note separate from frozen Word');
select pg_temp.assert_true((select count(*)=0 from public.claim_performance_review_mail(null,10)),'claimed row is never automatically reclaimed');
reset role;
select pg_temp.assert_true((select state='claimed' and claim_token=(current_setting('test.claim')::jsonb->>'claim_token')::uuid and claimed_at is not null from private.performance_review_mail_outbox),'durable claim matches returned token');
select pg_temp.assert_true((select final_document=current_setting('test.claim')::jsonb->'payload'->'document' from private.performance_reviews where id=current_setting('test.review_id')::uuid),'claim uses immutable manager document snapshot');
update private.performance_review_mail_outbox set claimed_at=clock_timestamp()-interval '100 years';
set local role service_role;
select pg_temp.assert_true((select count(*)=0 from public.claim_performance_review_mail()),'old unknown claim has no expiry resend');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a1000000-0000-4000-8000-000000000001","iat":1900000000}',true);
select pg_temp.assert_true(public.performance_review_workspace()->'reviews'->0=current_setting('test.submitted')::jsonb->'review','claim status never affects employee DTO bytes');
reset role;
